			"stays.go":   "unchanged",
		})
		tree2 := createTree(map[string]string{
			"added.go": "new file",
			"stays.go": "unchanged",
		})

		result, err := getAllChangedFilesBetweenTreesSlow(context.Background(), tree1, tree2)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
