		if len(result) != 2 {
			t.Fatalf("expected 2 changed files, got %d: %v", len(result), result)
		}
		if result[0] != "added.go" || result[1] != "deleted.go" {
			t.Errorf("expected [added.go, deleted.go], got %v", result)
		}
