			return "", fmt.Errorf("opencode export returned invalid JSON (%d bytes) and fallback export failed: %w", len(data), err)
		}

		fallbackData, err := os.ReadFile(tmpFile)
		if err != nil {
			return "", fmt.Errorf("failed to read fallback export file: %w", err)
		}
		if !json.Valid(fallbackData) {
			return "", fmt.Errorf("opencode export returned invalid JSON (%d bytes), fallback export also invalid (%d bytes)", len(data), len(fallbackData))
		}

		return tmpFile, nil
	}

	// Write to temp directory under .entire
	if err := os.MkdirAll(tmpDir, 0o750); err != nil {
		return "", fmt.Errorf("failed to create temp dir: %w", err)
	}

	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
		return "", fmt.Errorf("failed to write export file: %w", err)
	}

	return tmpFile, nil
}

